```javascript
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, Group, Mesh, PlaneGeometry, BoxGeometry, Color } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, attribute } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root container
  const root = new Group();
  root.userData.cleanup = () => {
    gsap.killTweensOf([root, ...allObjects]);
    Object.values(timelines).forEach(tl => tl?.kill());
  };

  const allObjects = [];
  const timelines = {};
  const railParams = {
    width: 3.6,
    height: 0.5,
    cornerRadius: 0.1,
    chamferEdge: 0.02,
    floatZ: 0.15,
    shadowZ: -0.06,
    shadowOpacity: 0.35,
  };

  const navItems = [
    { label: 'HOME', route: 'hub-home', active: true },
    { label: 'FEATURES', route: 'hub-features', active: false },
    { label: 'COLLECTION', route: 'hub-collection', active: false },
    { label: 'PRICING', route: 'hub-pricing', active: false },
    { label: 'JOURNAL', route: 'hub-journal', active: false },
  ];

  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    textInactive: '#a6adba',
    gradTop: '#1b1b23',
    gradBot: '#101015',
  };

  const spacing = {
    itemSpacing: 0.68,
    itemWidth: 0.6,
    itemHeight: 0.34,
    padding: 0.25,
    underlineWidth: 0.28,
    underlineHeight: 0.025,
    underlineOffset: 0.06,
  };

  // Create shadow plane beneath the rail
  const shadowGeom = new PlaneGeometry(railParams.width + 0.4, railParams.height + 0.2);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: railParams.shadowOpacity,
  });
  const shadowPlane = new Mesh(shadowGeom, shadowMat);
  shadowPlane.position.z = -railParams.floatZ + railParams.shadowZ;
  root.add(shadowPlane);
  allObjects.push(shadowPlane);

  // Create main rail with brushed-metal PBR gradient
  const railGeom = new THREE.RoundedBoxGeometry(
    railParams.width,
    railParams.height,
    0.02,
    8,
    8,
    8,
    railParams.cornerRadius
  );

  // Gradient texture node: vertical albedo ramp from #1b1b23 to #101015
  const gradientUV = uv();
  const topColor = new Color(colors.gradTop);
  const botColor = new Color(colors.gradBot);
  const gradMix = mix(
    vec3(topColor.r, topColor.g, topColor.b),
    vec3(botColor.r, botColor.g, botColor.b),
    gradientUV.y
  );

  const railMat = new MeshStandardNodeMaterial({
    colorNode: gradMix,
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });

  const rail = new Mesh(railGeom, railMat);
  rail.position.z = railParams.floatZ;
  rail.castShadow = true;
  rail.receiveShadow = true;
  root.add(rail);
  allObjects.push(rail);

  // Create nav items and their text layers
  const itemGroups = [];
  const textMeshes = [];
  const underlineBars = [];

  navItems.forEach((item, idx) => {
    const itemGroup = new Group();
    const xPos = (idx - 2) * spacing.itemSpacing; // Center around 0

    // Hit area mesh (invisible, for interaction)
    const hitGeom = new PlaneGeometry(spacing.itemWidth, spacing.itemHeight);
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
    const hitMesh = new Mesh(hitGeom, hitMat);
    itemGroup.add(hitMesh);

    // Text label
    const textColor = item.active ? colors.paper : colors.textInactive;
    const textSize = 0.13; // caption size in scene units for 13px
    const textMesh = ctx.fontAtlas.createText(item.label, {
      fontSize: 13,
      color: textColor,
      align: 'center',
      letterSpacingPx: 1.04, // 0.08em approximation
    });
    textMesh.position.y = 0.05; // Slight vertical offset within hit cell
    itemGroup.add(textMesh);
    textMeshes.push({ mesh: textMesh, item, index: idx, isActive: item.active });

    // Underline bar for active item only
    if (item.active) {
      const underlineGeom = new PlaneGeometry(spacing.underlineWidth, spacing.underlineHeight);
      const underlineMat = new MeshBasicNodeMaterial({
        color: new Color(colors.accent),
        emissive: new Color(colors.accent),
        emissiveIntensity: 1.8,
      });
      const underline = new Mesh(underlineGeom, underlineMat);
      underline.position.y = -(spacing.underlineOffset + spacing.underlineHeight * 0.5);
      underline.position.z = 0.01;
      itemGroup.add(underline);
      underlineBars.push({ mesh: underline, index: idx });
    }

    itemGroup.position.x = xPos;
    itemGroup.position.z = 0;
    itemGroup.userData.itemIndex = idx;
    itemGroup.userData.route = item.route;

    // Interaction handlers
    itemGroup.userData.handlers = itemGroup.userData.handlers || {};
    itemGroup.userData.handlers.click = () => {
      if (!item.active) {
        switchActiveItem(idx);
      }
      ctx.emit('navigate', { to: item.route });
    };

    itemGroup.userData.handlers.hover = () => {
      if (!item.active) {
        gsap.to(textMeshes[idx].mesh.material, {
          color: new Color(colors.paper),
          duration: 0.16,
          overwrite: 'auto',
        });
      }
    };

    itemGroup.userData.handlers.unhover = () => {
      if (!item.active) {
        gsap.to(textMeshes[idx].mesh.material, {
          color: new Color(colors.textInactive),
          duration: 0.16,
          overwrite: 'auto',
        });
      }
    };

    itemGroup.userData.handlers.press = () => {
      gsap.to(itemGroup.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
      gsap.to(itemGroup.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
    };

    itemGroup.userData.handlers.release = () => {
      gsap.to(itemGroup.position, {
        z: 0,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(itemGroup.scale, {
        x: 1,
        y: 1,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    };

    rail.add(itemGroup);
    itemGroups.push(itemGroup);
    allObjects.push(itemGroup);
  });

  // Function to switch active item and animate underline
  const switchActiveItem = (newIndex) => {
    const oldActive = navItems.findIndex(item => item.active);
    if (oldActive === newIndex) return;

    navItems[oldActive].active = false;
    navItems[newIndex].active = true;

    // Update text colors
    gsap.to(textMeshes[oldActive].mesh.material, {
      color: new Color(colors.textInactive),
      duration: 0.26,
      overwrite: 'auto',
    });
    gsap.to(textMeshes[newIndex].mesh.material, {
      color: new Color(colors.paper),
      duration: 0.26,
      overwrite: 'auto',
    });

    // Animate underline bar to new position
    if (underlineBars.length > 0) {
      const underline = underlineBars[0].mesh;
      const oldXPos = (oldActive - 2) * spacing.itemSpacing;
      const newXPos = (newIndex - 2) * spacing.itemSpacing;
      const xDelta = newXPos - oldXPos;

      const tl = gsap.timeline();
      tl.to(
        underline.position,
        {
          x: xDelta,
          duration: 0.26,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          overwrite: 'auto',
        },
        0
      );
      tl.to(
        underline.scale,
        {
          x: 1.04,
          y: 1.04,
          duration: 0.26,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          overwrite: 'auto',
        },
        0
      );
      tl.to(
        underline.scale,
        {
          x: 1,
          y: 1,
          duration: 0.26,
          ease: 'power4.out',
          overwrite: 'auto',
        },
        0.26
      );
      timelines.underlineSwitch?.kill();
      timelines.underlineSwitch = tl;
    }
  };

  // Mount animation: rise-in y +0.4 -> 0 over 700ms
  const mountTl = gsap.timeline();
  root.position.y = 0.4;
  mountTl.to(
    root.position,
    {
      y: 0,
      duration: 0.7,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      overwrite: 'auto',
    },
    0
  );
  timelines.mount = mountTl;

  // Attach root for event dispatching
  root.userData.handlers = {
    itemClick: (itemIndex) => {
      if (itemGroups[itemIndex]?.userData.handlers.click) {
        itemGroups[itemIndex].userData.handlers.click();
      }
    },
    itemHover: (itemIndex) => {
      if (itemGroups[itemIndex]?.userData.handlers.hover) {
        itemGroups[itemIndex].userData.handlers.hover();
      }
    },
    itemUnhover: (itemIndex) => {
      if (itemGroups[itemIndex]?.userData.handlers.unhover) {
        itemGroups[itemIndex].userData.handlers.unhover();
      }
    },
    itemPress: (itemIndex) => {
      if (itemGroups[itemIndex]?.userData.handlers.press) {
        itemGroups[itemIndex].userData.handlers.press();
      }
    },
    itemRelease: (itemIndex) => {
      if (itemGroups[itemIndex]?.userData.handlers.release) {
        itemGroups[itemIndex].userData.handlers.release();
      }
    },
  };

  return root;
}
